using System;using System.Linq;using System.Collections;using System.Collections.Generic;using System.IO;using Newtonsoft.Json.Linq;using UnityEngine;using SpatialWallpaper.Sdk.Native;using SpatialWallpaper.Sdk.Security;
namespace SpatialWallpaper.Sdk.Editor {
 internal sealed class ExternalNativeAuthorMetadata {
  readonly CompiledProgram program;readonly Transform[] nodes;readonly Dictionary<Transform,int> indices;
  internal ExternalNativeAuthorMetadata(CompiledProgram program,Transform root){this.program=program;nodes=root.GetComponentsInChildren<Transform>(true);indices=nodes.Select((value,index)=>new{value,index}).ToDictionary(v=>v.value,v=>v.index);}
  internal byte[] Encode(Vector3 frame){var graph=new JArray();foreach(var node in nodes){var components=new JArray(new JObject{{"kind","transform"},{"config",new JObject{{"position",Vector(node.localPosition)},{"rotation",new JArray(node.localRotation.x,node.localRotation.y,node.localRotation.z,node.localRotation.w)},{"scale",Vector(node.localScale)}}},{"fields",new JObject()},{"callbacks",new JArray()}});var light=node.GetComponent<Light>();if(light)components.Add(new JObject{{"kind","light"},{"config",SceneLightEncoding.Encode(light)},{"fields",new JObject()},{"callbacks",new JArray()}});int count=0;foreach(var script in node.GetComponents<MonoBehaviour>().Where(v=>program.Classes.ContainsKey(v.GetType().FullName))){if(!script.enabled||++count>1)throw new InvalidDataException("external:one-enabled-author-script-per-node");var cls=((JArray)program.Program["classes"]).Cast<JObject>().Single(v=>(string)v["id"]==program.ClassId(script.GetType()));components.Add(new JObject{{"kind","script"},{"config",new JObject{{"class",program.ClassId(script.GetType())}}},{"fields",Fields(script.GetType(),script,0)},{"callbacks",new JArray(((JArray)cls["methods"]).Where(m=>(string)m["id"]=="Start"||(string)m["id"]=="Update").Select(m=>(string)m["id"]))}});}graph.Add(new JObject{{"id","n"+graph.Count},{"parent",node==nodes[0]?-1:indices[node.parent]},{"components",components}});}return NativeScriptDefinition.Encode(program.Program,new JObject{{"frame",Vector(frame)},{"resources",new JArray()},{"prefabs",new JArray()},{"nodes",graph}});}
  JObject Fields(Type type,object instance,int depth){if(depth>16||instance==null||instance.GetType()!=type)throw new InvalidDataException("external:field-shape");var cls=((JArray)program.Program["classes"]).Cast<JObject>().Single(v=>(string)v["id"]==program.ClassId(type));var native=Cilbox.CilboxUtil.GetInstanceFieldsBaseFirst(type);var result=new JObject();foreach(JObject field in (JArray)cls["fields"]){string id=(string)field["id"];var f=native.Single(v=>program.FieldId(type,v.Name)==id);result[id]=Value(f.FieldType,f.GetValue(instance),depth+1);}return result;}
  JToken Value(Type type,object value,int depth){if(depth>16)throw new InvalidDataException("external:field-depth");if(value==null||value is UnityEngine.Object u&&!u)return JValue.CreateNull();string id=program.MapType(type);if(type.IsArray){var a=(Array)value;if(a.Rank!=1||a.Length>4096)throw new InvalidDataException("external:array-shape");return new JArray(a.Cast<object>().Select(v=>Value(type.GetElementType(),v,depth+1)));}if(RuleCatalog.Current.ListElement(id)!=null){var a=(IList)value;if(a.Count>4096)throw new InvalidDataException("external:list-shape");return new JArray(a.Cast<object>().Select(v=>Value(type.GenericTypeArguments[0],v,depth+1)));}switch(id){case "i32":return new JValue((int)value);case "f32":return new JValue((float)value);case "bool":return new JValue((bool)value);case "string":return new JValue((string)value);case "vector3":return Vector((Vector3)value);case "color":var c=(Color)value;return new JArray(c.r,c.g,c.b,c.a);case "node":var t=value is Transform transform?transform:((GameObject)value).transform;return new JValue(indices[t]);case "light":return new JValue(indices[((Light)value).transform]);case "sound":case "mesh":case "material":case "texture":case "cubemap":case "prefab":throw new InvalidDataException("external:author-resource-reference-not-supported:"+id);}if(typeof(MonoBehaviour).IsAssignableFrom(type))return new JObject{{"script",indices[((MonoBehaviour)value).transform]}};if(!program.Classes.ContainsKey(type.FullName))throw new InvalidDataException("external:author-field-type");return new JObject{{"fields",Fields(type,value,depth+1)}};}
  static JArray Vector(Vector3 v)=>new JArray(v.x,v.y,v.z);
 }
}
